  // Local Authority — Free Childcare 2-year-olds ──────────────────────────
  "la-free-childcare-2yr": {
    id: "la-free-childcare-2yr",
    name: "Free Childcare (disadvantaged 2-year-olds)",
    dept: "Local Authority",
    deptKey: "la",
    deadline: null,
    desc: "Early Learning for 2 year olds: 15 hours/week free childcare for 38 weeks for 2-year-olds whose family gets certain benefits or support. England only. Apply through the local council.",
    govuk_url: "https://www.gov.uk/help-with-childcare-costs/free-childcare-2-year-olds-extra-support",
    serviceType: "entitlement",
    proactive: true,
    gated: false,
    eligibility: {
      summary: "15 hours/week free childcare for eligible 2-year-olds in England. Qualifying criteria include receiving income-related benefits, being a looked-after child, having an EHC plan, receiving DLA, or leaving care.",
      universal: false,
      criteria: [
        { factor: "family", description: "Must have a 2-year-old child." },
        { factor: "income", description: "Parent/carer gets Universal Credit with household income of \xA315,400 a year or less after tax (not counting benefits), Income Support, income-based JSA, income-related ESA, or the guaranteed element of Pension Credit. Or the child has an EHC plan, gets DLA, is in care, or has left care under an adoption, special guardianship or child arrangements order. Some families who cannot claim benefits because of immigration status also qualify, subject to income and savings limits." },
        { factor: "geography", description: "England only." }
      ],
      keyQuestions: [
        "Do you have a child aged 2?",
        "Do you receive a qualifying benefit (UC with low household income, IS, income-based JSA, income-related ESA, or guaranteed Pension Credit)?",
        "Does the child have an EHC plan or receive DLA?",
        "Is the child a looked-after child?",
        "Do you live in England?"
      ],
      means_tested: true,
      evidenceRequired: ["Proof of qualifying benefit", "Child's date of birth", "National Insurance number"],
      ruleIn: ["Child aged 2", "On qualifying benefit or child has EHC plan/DLA", "Lives in England"],
      ruleOut: ["Child not aged 2", "Not on qualifying benefit and child has no additional needs", "Does not live in England"],
      rules: [
        {
          "type": "boolean",
          "field": "has_children",
          "expected": true,
          "label": "Has children"
        },
        {
          "type": "comparison",
          "field": "youngest_child_age",
          "operator": "==",
          "value": 2,
          "label": "Child must be aged 2"
        },
        {
          "type": "enum",
          "field": "nation",
          "oneOf": [
            "england"
          ],
          "label": "Must live in England"
        },
        {
          "type": "any",
          "label": "On qualifying benefit or child has additional needs",
          "rules": [
            {
              "type": "all",
              "label": "On Universal Credit with low income",
              "rules": [
                {
                  "type": "dependency",
                  "serviceId": "dwp-universal-credit",
                  "condition": "receiving",
                  "label": "Receiving Universal Credit"
                },
                {
                  "type": "comparison",
                  "field": "annual_income",
                  "operator": "<=",
                  "value": 15400,
                  "label": "Household income \xA315,400 a year or less after tax"
                }
              ]
            },
            {
              "type": "boolean",
              "field": "custom_facts.receiving_income_support",
              "expected": true,
              "label": "Receiving Income Support"
            },
            {
              "type": "boolean",
              "field": "custom_facts.receiving_income_based_jsa",
              "expected": true,
              "label": "Receiving income-based JSA"
            },
            {
              "type": "boolean",
              "field": "custom_facts.receiving_income_related_esa",
              "expected": true,
              "label": "Receiving income-related ESA"
            },
            {
              "type": "boolean",
              "field": "custom_facts.child_has_ehc_plan",
              "expected": true,
              "label": "Child has an Education, Health and Care (EHC) plan"
            },
            {
              "type": "boolean",
              "field": "custom_facts.child_receives_dla",
              "expected": true,
              "label": "Child receives Disability Living Allowance"
            },
            {
              "type": "boolean",
              "field": "custom_facts.child_looked_after_or_care_leaver",
              "expected": true,
              "label": "Child is looked-after or has left care"
            }
          ]
        }
      ]
    },
    agentInteraction: {
      methods: ["in-person", "phone"],
      apiAvailable: false,
      onlineFormUrl: "https://www.gov.uk/help-with-childcare-costs/free-childcare-2-year-olds-extra-support",
      authRequired: "none",
      agentCanComplete: "partial",
      agentSteps: [
        "Check eligibility based on benefit receipt or child's needs",
        "Guide user to apply through the early years team or Family Information Service at their local council, close to the child's 2nd birthday",
        "Explain the 15 hours/week entitlement (38 weeks/year)",
        "Advise on finding eligible childcare providers"
      ]
    },
    nations: ["england"]
  },
