// src/provenance.ts
import { createHash } from "node:crypto";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
var __dirname = dirname(fileURLToPath(import.meta.url));
var PROVENANCE_PATH = join(__dirname, "..", "data", "provenance.json");
function hashValue(value) {
  return createHash("sha256").update(stableStringify(value)).digest("hex").slice(0, 16);
}
function stableStringify(value) {
  if (value === null || typeof value !== "object") return JSON.stringify(value) ?? "null";
  if (Array.isArray(value)) return `[${value.map(stableStringify).join(",")}]`;
  const entries = Object.entries(value).filter(([, v]) => v !== void 0).sort(([a], [b]) => a < b ? -1 : a > b ? 1 : 0);
  return `{${entries.map(([k, v]) => `${JSON.stringify(k)}:${stableStringify(v)}`).join(",")}}`;
}
function getFieldValue(node, fieldPath) {
  let current = node;
  for (const segment of fieldPath.split(".")) {
    if (current == null) return void 0;
    current = current[segment];
  }
  return current;
}

// src/provenance-view.ts
var store = provenance_default;
var GUIDE = "Where each factual field came from. confirmed: found on the cited page, with the quote. inferred: an authored judgement with no published source. unverified: checked and not found, or the value changed after it was checked. unsourced: never checked. Treat anything other than confirmed as unconfirmed, and say so to the user when it matters to their decision. Quotes are re-checked against the live page weekly.";
function claimFields(node) {
  const out = [
    { path: "govuk_url" },
    { path: "deptKey", about: "Which body delivers the service" },
    { path: "desc" },
    { path: "eligibility.summary" },
    { path: "eligibility.criteria" }
  ];
  if (node.deadline) out.push({ path: "deadline" });
  if (node.nations) out.push({ path: "nations" });
  for (const key of Object.keys(node.financialData?.rates ?? {})) {
    out.push({ path: `financialData.rates.${key}` });
  }
  if (node.contactInfo?.phone?.number) out.push({ path: "contactInfo.phone.number" });
  (node.contactInfo?.additionalPhones ?? []).forEach((p, i) => out.push({ path: `contactInfo.additionalPhones.${i}.number`, about: p.label }));
  const walk = (rule, path) => {
    if (rule.type === "all" || rule.type === "any" || rule.type === "not") {
      rule.rules.forEach((r, i) => walk(r, `${path}.rules.${i}`));
    } else if (rule.type === "comparison") {
      out.push({ path: `${path}.value`, about: `Eligibility rule: ${rule.label}` });
    } else if (rule.type === "deadline") {
      out.push({ path: `${path}.maxDays`, about: `Deadline rule: ${rule.label}` });
    }
  };
  (node.eligibility.rules ?? []).forEach((r, i) => walk(r, `eligibility.rules.${i}`));
  if (node.agentInteraction) out.push({ path: "agentInteraction.agentSteps" });
  return out;
}
function evidenceFor(node, path, about) {
  const record2 = store.fields[`${node.id}#${path}`];
  if (!record2) return { status: "unsourced", ...about ? { about } : {} };
  const base = {
    status: record2.confidence,
    ...about ? { about } : {},
    source: record2.sourceUrl || void 0,
    quote: record2.sourceQuote || void 0,
    method: record2.method,
    checkedAt: record2.verifiedAt.slice(0, 10)
  };
  if (hashValue(getFieldValue(node, path)) !== record2.valueHash) {
    return { ...base, status: "unverified", quote: void 0, note: "Value has changed since it was checked." };
  }
  if (record2.confidence !== "confirmed" && record2.rationale) base.note = record2.rationale;
  return base;
}
function provenanceFor(node) {
  const fields = {};
  const summary = { confirmed: 0, inferred: 0, unverified: 0, unsourced: 0 };
  for (const { path, about } of claimFields(node)) {
    const ev = evidenceFor(node, path, about);
    fields[path] = ev;
    summary[ev.status]++;
  }
  return { guide: GUIDE, summary, fields };
}
function sourcingSummary(node) {
  const { summary } = provenanceFor(node);
  return { confirmed: summary.confirmed, notConfirmed: summary.inferred + summary.unverified + summary.unsourced };
}
function ruleValueSourcing(node) {
  const rulePaths = claimFields(node).filter((f) => f.path.startsWith("eligibility.rules."));
  if (!rulePaths.length) return null;
  const confirmed = rulePaths.filter((f) => evidenceFor(node, f.path).status === "confirmed").length;
  return { confirmed, total: rulePaths.length };
}

// src/graph-server.ts
var server = new McpServer({
  name: "uk-services-graph",
  version: "1.0.0"
});
server.tool(
  "list_life_events",
  `List all 16 UK government life events supported by the journey planner.

Each life event is a named entry point into the service graph. Call this first to ground the conversation in the available taxonomy, then identify which event(s) match the user's situation and call plan_journey.

Life events can be combined \u2014 someone having a baby who also just lost their job should use ["baby", "job-loss"] together. The graph deduplicates shared services across events.`,
  {},
  async () => {
    const events = LIFE_EVENTS.map((evt) => ({
      id: evt.id,
      name: evt.name,
      description: evt.desc,
      entryNodeCount: evt.entryNodes.length
    }));
    return {
      content: [{ type: "text", text: JSON.stringify(events, null, 2) }]
    };
  }
);
server.tool(
  "plan_journey",
  `Compute a personalised government service journey for one or more life events.

Returns services grouped into phases:
- Phase 1 = gateway services that must happen first (e.g. registering a birth or death)
- Later phases = services that are unlocked by earlier ones

Each service includes eligibility signals:
  universal      \u2014 true means virtually anyone qualifies; no screening needed
  proactive      \u2014 true means proactively mention this from context clues
  gated          \u2014 true means only surface after confirming a prerequisite
  means_tested   \u2014 true means income/capital assessment required
  eligibilitySummary \u2014 one-sentence plain-English eligibility description

Optional enrichments (present where applicable):
  nations[]      \u2014 devolved services limited to specific UK nations (absent = UK-wide)

Each service also carries sourcing: { confirmed, notConfirmed } \u2014 how many of its factual fields (rates, deadlines, eligibility rule values, links, contact numbers, descriptions) are confirmed against a cited official page. Call get_service for the per-field sources and quotes.

Use the triggeredBy field to explain why each service appears. Use deadline to highlight urgency.

Call get_service for any service the user wants to explore \u2014 it returns the full detail omitted here:
agentInteraction (application methods, what the agent can do step-by-step, online form URL),
financialData (benefit rates and amounts, with the tax year they apply to), and contactInfo (helpline phone, opening hours, webchat).`,
  {
    life_event_ids: external_exports.array(external_exports.string()).min(1).describe(
      'One or more life event IDs from list_life_events (e.g. ["baby", "moving"] or ["bereavement"]). Multiple IDs are merged into a single journey, deduplicating shared services.'
    )
  },
  async ({ life_event_ids }) => {
    const validIds = new Set(LIFE_EVENTS.map((e) => e.id));
    const unknown2 = life_event_ids.filter((id) => !validIds.has(id));
    if (unknown2.length) {
      return {
        content: [{
          type: "text",
          text: `Unknown life event IDs: ${unknown2.join(", ")}. Call list_life_events to see valid IDs.`
        }]
      };
    }
    const journey = buildJourney(life_event_ids);
    const result = {
      ...journey,
      phases: journey.phases.map((phase) => ({
        ...phase,
        services: phase.services.map((svc) => ({ ...svc, sourcing: sourcingSummary(NODES[svc.id]) }))
      }))
    };
    return {
      content: [{ type: "text", text: JSON.stringify(result, null, 2) }]
    };
  }
);
server.tool(
  "get_service",
  `Get full details about a specific government service, including its complete eligibility model and agent interaction capabilities.

Returns:
- Service description, deadline, GOV.UK URL, and type classification
- Full eligibility: summary, criteria (typed factors), key questions to ask the user, auto-qualifiers (conditions that confirm eligibility immediately), common exclusions, and evidence required
- Agent interaction: application methods, API availability, online form URLs, authentication requirements, what the agent can do step-by-step, and MissingBenefit.com calculator ID if available
- Financial data (where applicable): structured rates with amounts, frequency and the tax year they apply to
- Nations (where applicable): which UK nations the service covers
- Contact info: helpline phone number (with textphone, Relay UK, Welsh, BSL), opening hours, webchat URL, office locator URL. Resolved from service-specific data or department default.
- Graph position: prerequisite services, services this unlocks, and which life events trigger it
- Provenance: for every factual field, whether it is confirmed against an official page (with the source URL, a verbatim quote and the date checked), inferred, unverified or unsourced

Use this when the user asks for more detail about a service, or when you need to assess their eligibility for it. The keyQuestions tell you exactly what to ask. The autoQualifiers let you confirm eligibility without interrogating the user further. The agentInteraction.agentSteps tell you exactly what actions you can take on the user's behalf. The contactInfo tells you the exact helpline number and hours to share when the user needs to speak to someone. The provenance tells you which of these facts you can cite, and which you should present as unconfirmed.`,
  {
    service_id: external_exports.string().describe(
      'The service node ID (e.g. "dwp-pip", "gro-register-birth", "hmcts-probate"). These IDs appear in plan_journey results.'
    )
  },
  async ({ service_id }) => {
    const service = getServiceWithContext(service_id);
    if (!service) {
      return {
        content: [{
          type: "text",
          text: `No service found with ID: "${service_id}". IDs appear in plan_journey results. Use list_life_events + plan_journey to discover valid IDs.`
        }]
      };
    }
    const withProvenance = { ...service, provenance: provenanceFor(NODES[service_id]) };
    return {
      content: [{ type: "text", text: JSON.stringify(withProvenance, null, 2) }]
    };
  }
);
